import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    if n == 0:
        print("NO")
        return

    primes = []
    is_prime = [True] * (n + 1)
    for num in range(2, n + 1):
        if is_prime[num]:
            primes.append(num)
            for mult in range(num * num, n + 1, num):
                is_prime[mult] = False

    groups = {}
    for p in primes:
        if p > n:
            break
        group = set()
        for i in range(1, n // p + 1):
            pos = p * i - 1
            group.add(pos)
        if not group:
            continue
        min_pos = min(group)
        if min_pos not in groups:
            groups[min_pos] = set()
        groups[min_pos].update(group)

    used = [False] * n
    for root, members in groups.items():
        for pos in members:
            used[pos] = True

    from collections import Counter
    counts = Counter(s)

    res = [''] * n
    assigned_count = {}

    for root, members in groups.items():
        needed = len(members)
        found_char = None
        for char, count in counts.items():
            current_used = assigned_count.get(char, 0)
            if count - current_used >= needed:
                found_char = char
                break

        if found_char is None:
            print("NO")
            return

        for pos in members:
            res[pos] = found_char
            assigned_count[found_char] = assigned_count.get(found_char, 0) + 1

    remaining_chars = []
    for char, total in counts.items():
        used_count = assigned_count.get(char, 0)
        remaining_chars.extend([char] * (total - used_count))

    idx = 0
    for i in range(n):
        if not used[i]:
            res[i] = remaining_chars[idx]
            idx += 1

    print("YES")
    print("".join(res))

if __name__ == "__main__":
    solve()
